// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DnGmxBatchingManager, IERC20, IGlpManager, IRewardRouterV2} from "../src/DnGmxBatchingManager.sol";

contract InvMutTest is Test {
    DnGmxBatchingManager c;
    ERC20Mock token;

    function setUp() public {
        c = new DnGmxBatchingManager();
        token = new ERC20Mock();
        GlpManagerMock gm = new GlpManagerMock();
        RewardRouterMock rr = new RewardRouterMock();
        c.initialize(IERC20(address(token)), IERC20(address(token)), IRewardRouterV2(address(rr)), IGlpManager(address(gm)), address(0xBEEF), address(this));
    }

    function testFuzz_property(uint256 amount, address caller, uint256 t) public {
        vm.assume(caller != address(0) && caller != c.keeper() && caller != address(c));
        amount = bound(amount, 1, type(uint128).max);
        t = bound(t, 901, 10_000_000);

        // only the vault may depositToken; build dnGmxJuniorVaultGlpBalance > 0
        vm.prank(address(0xBEEF));
        c.depositToken(address(token), amount, 0);
        assertTrue(c.dnGmxJuniorVaultGlpBalance() == amount, "setup");

        // cooldown so the body would pass if access control were missing
        vm.warp(block.timestamp + t);

        vm.prank(caller);
        try c.executeBatchDeposit() {
            // in a correct contract a non-keeper can never get here
            assertTrue(c.dnGmxJuniorVaultGlpBalance() == amount, "non-keeper reset glp balance");
        } catch {
            assertTrue(c.dnGmxJuniorVaultGlpBalance() == amount, "balance changed on revert");
        }
    }
}

contract ERC20Mock {
    function transferFrom(address, address, uint256) external pure returns (bool) { return true; }
    function transfer(address, uint256) external pure returns (bool) { return true; }
    function approve(address, uint256) external pure returns (bool) { return true; }
}

contract RewardRouterMock {
    function mintAndStakeGlp(address, uint256 amount, uint256, uint256) external pure returns (uint256) { return amount; }
}

contract GlpManagerMock {
    function vault() external pure returns (address) { return address(1); }
}
